import { authorizeAccessOwner, withAccessIdentity } from "@recallfeed/api/access";
import { app } from "@recallfeed/api/app";
// @ts-expect-error `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as nextHandler } from "./.open-next/worker.js";
import type { ReflectionFeedEnv } from "./src/env";

/** `/api/feed` reaches the shared API as `/feed`. */
const API_PREFIX = "/api";

/**
 * The production entry point.
 *
 * Every request is checked before anything else runs: the Access token is verified and must belong to
 * `OWNER_EMAIL` (401, 403, or a generic 500 if misconfigured). The verified identity is then handed to
 * the shared API and to Next.js as `ctx.access`. Paths under `/api` go to the shared Hono app with the
 * prefix removed; everything else goes to the Next.js handler OpenNext generated.
 *
 * Static asset files (scripts, styles) are served by Cloudflare before this runs. Access still protects
 * them, and they hold no user data.
 */
export default {
  async fetch(request: Request, env: ReflectionFeedEnv, ctx: ExecutionContext): Promise<Response> {
    const verified = await authorizeAccessOwner(request, env);
    if (!verified.ok) {
      return verified.response;
    }
    const ownerCtx = withAccessIdentity(ctx, verified.identity);

    const url = new URL(request.url);
    if (url.pathname === API_PREFIX || url.pathname.startsWith(`${API_PREFIX}/`)) {
      url.pathname = url.pathname.slice(API_PREFIX.length) || "/";
      return app.fetch(new Request(url, request), env, ownerCtx);
    }
    return nextHandler.fetch(request, env, ownerCtx);
  },
} satisfies ExportedHandler<ReflectionFeedEnv>;
